{"command": "echo "import pickle
from copy import deepcopy
import numpy.polynomial.polynomial as poly

x = poly.Polynomial([1, 2, 3])
print('Original:', x)

try:
    y = deepcopy(x)
    print('Deep copy:', y)
except Exception as e:
    print('Error:', e)

try:
    z = pickle.dumps(x)
    w = pickle.loads(z)
    print('Pickled and unpickled:', w)
except Exception as e:
    print('Error:', e)" > test_polynomial_copy.py"}

